#!/bin/bash\n# -*- coding: utf-8 -*-\n# تثبيت أداة تحليل محتوى Facebook على Kali Linux\n# Facebook Content Analyzer - Installation Script for Kali Linux\n\necho \"╔════════════════════════════════════════════════════════════════╗\"\necho \"║  🔍 أداة تحليل محتوى Facebook                                 ║\"\necho \"║  Facebook Content Analyzer Installation                        ║\"\necho \"║  © 2026 Muqtada Diaa                                          ║\"\necho \"╚════════════════════════════════════════════════════════════════╝\"\necho \"\"\n\n# التحقق من صلاحيات المسؤول\nif [[ $EUID -ne 0 ]]; then\n   echo \"🔴 هذا البرنامج يتطلب صلاحيات مسؤول\"\n   echo \"الرجاء تشغيل: sudo bash install.sh\"\n   exit 1\nfi\n\necho \"📦 تحديث قائمة الحزم...\"\napt-get update -y > /dev/null 2>&1\n\necho \"📥 تثبيت Python 3 والمتطلبات الأساسية...\"\napt-get install -y python3 python3-pip python3-venv git wget curl > /dev/null 2>&1\n\necho \"📂 إنشاء المجلد الرئيسي...\"\nmkdir -p /opt/facebook-analyzer\ncd /opt/facebook-analyzer\n\necho \"📥 استنساخ المستودع...\"\ngit clone https://github.com/daham65244-afk/facebook-content-analyzer.git . 2>/dev/null || {\n    echo \"⚠️  لم يتمكن من استنساخ من GitHub، جاري التثبيت المحلي...\"\n}\n\necho \"🐍 إنشاء بيئة Python الافتراضية...\"\npython3 -m venv venv\nsource venv/bin/activate\n\necho \"📦 تثبيت المكتبات المطلوبة...\"\npip install --upgrade pip > /dev/null 2>&1\npip install -r requirements.txt > /dev/null 2>&1\n\necho \"🔗 إنشاء رابط للأمر العام...\"\ncat > /usr/local/bin/facebook-analyzer << 'EOF'\n#!/bin/bash\ncd /opt/facebook-analyzer\nsource venv/bin/activate\npython3 cli.py \"$@\"\nEOF\n\nchmod +x /usr/local/bin/facebook-analyzer\n\necho \"🔐 إعدادات الأذونات...\"\nchown -R root:root /opt/facebook-analyzer\nchmod -R 755 /opt/facebook-analyzer\nchmod +x /opt/facebook-analyzer/cli.py\nchmod +x /opt/facebook-analyzer/analyzer.py\n\necho \"\"\necho \"╔════════════════════════════════════════════════════════════════╗\"\necho \"║  ✅ تم التثبيت بنجاح!                                          ║\"\necho \"╚════════════════════════════════════════════════════════════════╝\"\necho \"\"\necho \"📋 كيفية الاستخدام:\"\necho \"\"\necho \"1️⃣  الوضع التفاعلي:\"\necho \"   facebook-analyzer -i\"\necho \"\"\necho \"2️⃣  تحليل نص مباشر:\"\necho \"   facebook-analyzer -t \\\"النص المراد تحليله\\\"\"\necho \"\"\necho \"3️⃣  تحليل ملف:\"\necho \"   facebook-analyzer -f /path/to/file.txt\"\necho \"\"\necho \"4️⃣  تحليل مع رابط:\"\necho \"   facebook-analyzer -t \\\"النص\\\" -u \\\"https://example.com\\\"\"\necho \"\"\necho \"5️⃣  إخراج JSON:\"\necho \"   facebook-analyzer -t \\\"النص\\\" -o json\"\necho \"\"\necho \"6️⃣  إخراج HTML:\"\necho \"   facebook-analyzer -t \\\"النص\\\" -o html\"\necho \"\"\necho \"7️⃣  الحصول على المساعدة:\"\necho \"   facebook-analyzer --help\"\necho \"\"\necho \"📂 مكان التثبيت: /opt/facebook-analyzer\"\necho \"🔍 الملفات الرئيسية:\"\necho \"   - analyzer.py : محرك التحليل\"\necho \"   - cli.py : واجهة سطر الأوامر\"\necho \"   - requirements.txt : المتطلبات\"\necho \"\"\necho \"🌐 تم التطوير بواسطة: Muqtada Diaa\"\necho \"📅 النسخة: 1.0.0\"\necho \"\"\n"
